INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h29h-2017-q31','exam-sg','電子署名法','standard','single_choice','【2017年度 平成29年春期 午前 問31】電子署名法に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"電子署名には，電磁的記録以外でコンピュータ処理の対象とならないものも含まれる。"},{"id":"b","text":"電子署名には，民事訴訟法における押印と同様の効力が認められる。"},{"id":"c","text":"電子署名の認証業務を行うことができるのは，政府が運営する認証局に限られる。"},{"id":"d","text":"電子署名は共通鍵暗号技術によるものに限られる。"}]','"b"','正解はイ。一定の要件を満たす電子署名が付された電磁的記録には，真正に成立したものと推定される法的効果がある。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q32','exam-sg','電子商取引・契約','standard','single_choice','【2017年度 平成29年春期 午前 問32】インターネットショッピングで商品を購入するとき，売買契約が成立するのはどの時点か。','[{"id":"a","text":"消費者からの購入申込みが事業者に到達した時点"},{"id":"b","text":"事業者が消費者宛てに承諾の通知を発信した時点"},{"id":"c","text":"事業者からの承諾の通知が消費者に到達した時点"},{"id":"d","text":"商品が消費者の手元に到達した時点"}]','"c"','正解はウ。原則として，事業者の承諾通知が消費者に到達した時点で売買契約が成立する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q33','法務・不正競争防止法','standard','single_choice','【2017年度 平成29年春期 午前 問33】不正競争防止法で保護されるものはどれか。','[{"id":"a","text":"特許権を取得した発明"},{"id":"b","text":"頒布されている自社独自のシステム開発手順書"},{"id":"c","text":"秘密として管理していない，自社システムを開発するための重要な設計書"},{"id":"d","text":"秘密として管理している，事業活動用の非公開の顧客名簿"}]','"d"','正解はエ。秘密管理性・有用性・非公知性を満たす営業秘密は，不正競争防止法による保護の対象となる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q34','法務・著作権','standard','single_choice','【2017年度 平成29年春期 午前 問34】著作権法による保護の対象となるものはどれか。','[{"id":"a","text":"ソースプログラムそのもの"},{"id":"b","text":"データ通信のプロトコル"},{"id":"c","text":"プログラムに組み込まれたアイディア"},{"id":"d","text":"プログラムのアルゴリズム"}]','"a"','正解はア。プログラムの表現であるソースコードは著作物になり得るが，アイデアやアルゴリズム自体は保護対象ではない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q35','労務管理・労働基準法','standard','single_choice','【2017年度 平成29年春期 午前 問35】時間外労働に関する記述のうち，労働基準法に照らして適切なものはどれか。','[{"id":"a","text":"裁量労働制を導入している場合，法定労働時間外の労働は従業員の自己管理としてよい。"},{"id":"b","text":"事業場外労働が適用されている営業担当者には時間外手当の支払はない。"},{"id":"c","text":"年俸制が適用される従業員には時間外手当の支払はない。"},{"id":"d","text":"法定労働時間外の労働を労使協定（36協定）なしで行わせるのは違法である。"}]','"d"','正解はエ。法定労働時間を超えて労働させるには，原則として36協定の締結・届出など法定の手続が必要である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q36','特権ID管理','standard','single_choice','【2017年度 平成29年春期 午前 問36】特権IDの不正使用を発見するコントロールとして，最も有効なものはどれか。','[{"id":"a","text":"特権IDの貸出し・返却記録と，特権IDの利用ログを照合する。"},{"id":"b","text":"特権IDの使用を許可された者も，通常の操作では一般利用者IDを使用する。"},{"id":"c","text":"特権IDの使用を必要とする者は，使用の都度，特権IDの貸出しを受ける。"},{"id":"d","text":"特権IDの設定内容や使用範囲を用途に応じて細分化する。"}]','"a"','正解はア。貸出し記録と利用ログを照合すれば，申請・承認されていない特権利用を検知しやすい。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q37','システム監査・テスト','standard','single_choice','【2017年度 平成29年春期 午前 問37】システムテストの監査におけるチェックポイントのうち，最も適切なものはどれか。','[{"id":"a","text":"テスト計画は事前に利用者側の責任者だけで承認されていること"},{"id":"b","text":"テストは実際に業務が行われている本番環境で実施されていること"},{"id":"c","text":"独立性を考慮し，テストは利用者側の担当者だけで行われていること"},{"id":"d","text":"例外ケースや異常ケースを想定したテストが行われていること"}]','"d"','正解はエ。正常系だけでなく例外・異常ケースも検証することで，障害時の動作や入力チェックを確認できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q38','システム監査・監査報告','standard','single_choice','【2017年度 平成29年春期 午前 問38】システム監査人が監査報告書の原案について被監査部門と意見交換を行う目的として，最も適切なものはどれか。','[{"id":"a","text":"監査依頼者に監査報告書を提出する前に，被監査部門に監査報告を行うため"},{"id":"b","text":"改善勧告について，被監査部門の責任者の承認を受けるため"},{"id":"c","text":"監査報告書に記載する指摘事項及び改善勧告について，事実誤認がないことを確認するため"},{"id":"d","text":"調査が不足している事項を口頭で確認し，不足事項の追加調査に代えるため"}]','"c"','正解はウ。被監査部門との意見交換は，事実関係の誤りを確認するために行い，監査人の独立した判断や追加調査を置き換えるものではない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q39','システム監査・障害管理','standard','single_choice','【2017年度 平成29年春期 午前 問39】システム障害管理の監査で判明した状況のうち，監査人が監査報告書で報告すべき指摘事項はどれか。','[{"id":"a","text":"システム障害対応マニュアルが作成され，オペレータへの周知が図られている。"},{"id":"b","text":"データベースが障害の被害を受けた場合を想定し，規程に従ってバックアップを取得している。"},{"id":"c","text":"障害の種類・発生箇所・影響度合いに関係なく，共通の連絡・報告ルートが定められている。"},{"id":"d","text":"全てのシステム障害について障害記録を残し，責任者の承認を得ることが定められている。"}]','"c"','正解はウ。障害の種類や影響度に応じた連絡・報告ルートが必要であり，すべてを一律に扱う設計は不適切である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q40','運用テスト・業務要件','standard','single_choice','【2017年度 平成29年春期 午前 問40】利用部門の利用者と情報システム部門の運用者が合同でシステムの運用テストを実施する。利用者が優先して確認すべき事項はどれか。','[{"id":"a","text":"オンライン処理やバッチ処理などが運用手順どおりに稼働すること"},{"id":"b","text":"システムが決められた業務手順どおりに稼働すること"},{"id":"c","text":"システムが目標とする性能要件を満たしていること"},{"id":"d","text":"全てのアプリケーションプログラムが仕様どおりに機能すること"}]','"b"','正解はイ。利用者は，実際の業務手順に沿って必要な業務が正しく完了できるかを優先して確認する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja');
